-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 0006_views_and_analytics.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- 0006_views_and_analytics.sql
-- Ignite Interior Decor: read models for the UI.
--
-- The directory views are owned by the migration role (postgres), so they read
-- base tables without RLS; each one is declared security_barrier and filters
-- its rows with the SECURITY DEFINER access helpers in its WHERE clause, so a
-- caller only ever receives rows they are entitled to. activity_feed instead
-- uses security_invoker so the audit_logs RLS policy applies directly.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- project_directory: projects + client name + site manager + deadline maths.
-- Contains NO money columns.
-- -----------------------------------------------------------------------------
create view public.project_directory
with (security_barrier = true)
as
select
  p.id,
  p.project_code,
  p.client_id,
  p.name,
  p.project_type,
  p.site_address,
  p.city,
  p.start_date,
  p.expected_completion_date,
  p.handover_date,
  p.actual_handover_date,
  p.status,
  p.progress_percentage,
  p.priority,
  p.current_milestone,
  p.notes,
  p.last_update_at,
  p.last_updated_by,
  p.archived_at,
  p.created_at,
  p.updated_at,
  p.created_by,
  c.name as client_name,
  c.client_code,
  sm.site_manager_id,
  sm.site_manager_name,
  coalesce(sm.site_manager_ids, array[]::uuid[]) as site_manager_ids,
  p.expected_completion_date as deadline_date,
  (p.expected_completion_date - public.app_today())::int as days_remaining,
  (p.expected_completion_date is not null
     and p.expected_completion_date < public.app_today()
     and p.status not in ('completed', 'cancelled')) as is_overdue,
  case
    when p.status = 'completed' then 'completed'
    when p.status = 'cancelled' then 'cancelled'
    when p.expected_completion_date is null then 'no_date'
    when p.expected_completion_date < public.app_today() then 'overdue'
    when p.expected_completion_date = public.app_today() then 'due_today'
    when p.expected_completion_date = public.app_today() + 1 then 'due_tomorrow'
    when p.expected_completion_date <= public.app_today() + 7 then 'due_7'
    when p.expected_completion_date <= public.app_today() + 14 then 'due_14'
    when p.expected_completion_date <= public.app_today() + 30 then 'due_30'
    else 'on_track'
  end as deadline_state,
  coalesce(mr.open_count, 0)::int as open_material_requests,
  coalesce(mr.total_count, 0)::int as total_material_requests,
  -- Effective handover date used by the "upcoming handovers" KPI and widget:
  -- sort / filter on this column so the list matches the count.
  coalesce(p.handover_date, p.expected_completion_date) as handover_or_deadline
from public.projects p
join public.clients c on c.id = p.client_id
left join lateral (
  select
    (array_agg(m.user_id order by m.assigned_at, m.id))[1] as site_manager_id,
    (array_agg(pr.full_name order by m.assigned_at, m.id))[1] as site_manager_name,
    array_agg(m.user_id order by m.assigned_at, m.id) as site_manager_ids
  from public.project_members m
  join public.profiles pr on pr.id = m.user_id
  where m.project_id = p.id and m.status = 'active' and m.member_role = 'site_manager'
) as sm on true
left join lateral (
  select
    count(*) filter (where r.status not in ('delivered', 'rejected', 'cancelled')) as open_count,
    count(*) as total_count
  from public.material_requests r
  where r.project_id = p.id and r.archived_at is null
) as mr on true
where public.can_access_project(p.id);

-- -----------------------------------------------------------------------------
-- project_financial_summary: owner / explicitly granted members only.
-- material_variance compares like with like: actual minus estimate over the
-- request items that carry both costs (material_variance_estimated_cost /
-- material_variance_actual_cost are those two totals). Items still awaiting
-- an actual cost do not offset real overruns.
-- -----------------------------------------------------------------------------
create view public.project_financial_summary
with (security_barrier = true)
as
select
  p.id as project_id,
  p.project_code,
  p.name as project_name,
  p.client_id,
  c.name as client_name,
  p.status,
  p.archived_at,
  coalesce(f.project_cost, 0) as project_cost,
  coalesce(f.advance_received, 0) as advance_received,
  coalesce(mc.estimated, 0) as material_estimated_cost,
  coalesce(mc.approved, 0) as material_approved_cost,
  coalesce(mc.actual, 0) as material_actual_cost,
  (coalesce(mc.variance_actual, 0) - coalesce(mc.variance_estimated, 0)) as material_variance,
  coalesce(mc.variance_estimated, 0) as material_variance_estimated_cost,
  coalesce(mc.variance_actual, 0) as material_variance_actual_cost
from public.projects p
join public.clients c on c.id = p.client_id
left join public.project_financials f on f.project_id = p.id
left join lateral (
  select sum(r.estimated_cost) as estimated,
         sum(r.approved_cost) as approved,
         sum(r.actual_cost) as actual,
         sum(r.variance_estimated_cost) as variance_estimated,
         sum(r.variance_actual_cost) as variance_actual
  from public.material_requests r
  where r.project_id = p.id
    and r.archived_at is null
    and r.status not in ('rejected', 'cancelled')
) as mc on true
where public.can_view_project_financials(p.id);

-- -----------------------------------------------------------------------------
-- client_directory: owner, or site managers of one of the client's projects.
-- Project aggregates only include projects the caller can access.
-- -----------------------------------------------------------------------------
create view public.client_directory
with (security_barrier = true)
as
select
  c.id,
  c.client_code,
  c.name,
  c.email,
  c.phone,
  c.alternate_phone,
  c.address,
  c.city,
  c.state,
  c.country,
  c.notes,
  c.archived_at,
  c.created_at,
  c.updated_at,
  c.created_by,
  coalesce(agg.project_count, 0)::int as project_count,
  coalesce(agg.active_project_count, 0)::int as active_project_count,
  latest.id as latest_project_id,
  latest.name as latest_project_name,
  latest.status as latest_project_status,
  latest.progress_percentage as latest_progress,
  latest.start_date as latest_start_date,
  latest.handover_date as latest_handover_date,
  (latest.expected_completion_date - public.app_today())::int as latest_days_remaining,
  latest_sm.full_name as site_manager_name
from public.clients c
left join lateral (
  select count(*) as project_count,
         count(*) filter (where p.status in ('planning', 'design', 'approval', 'procurement', 'execution',
                                             'finishing', 'handover_pending', 'delayed')) as active_project_count
  from public.projects p
  where p.client_id = c.id and p.archived_at is null and public.can_access_project(p.id)
) as agg on true
left join lateral (
  select p.id, p.name, p.status, p.progress_percentage, p.start_date, p.handover_date, p.expected_completion_date
  from public.projects p
  where p.client_id = c.id and p.archived_at is null and public.can_access_project(p.id)
  order by p.start_date desc nulls last, p.created_at desc
  limit 1
) as latest on true
left join lateral (
  select pr.full_name
  from public.project_members m
  join public.profiles pr on pr.id = m.user_id
  where m.project_id = latest.id and m.status = 'active' and m.member_role = 'site_manager'
  order by m.assigned_at, m.id
  limit 1
) as latest_sm on true
where public.can_access_client(c.id);

-- -----------------------------------------------------------------------------
-- material_request_directory
-- approved_cost, actual_cost and cost_variance are NULL unless the caller may
-- see approved/actual costs (owner, admins, members granted financial access);
-- site managers otherwise see estimated costs only.
-- -----------------------------------------------------------------------------
create view public.material_request_directory
with (security_barrier = true)
as
select
  r.id,
  r.request_code,
  r.project_id,
  r.client_id,
  r.requested_by,
  r.assigned_admin,
  r.title,
  r.required_date,
  r.priority,
  r.status,
  r.estimated_cost,
  case when cv.allowed then r.approved_cost end as approved_cost,
  case when cv.allowed then r.actual_cost end as actual_cost,
  r.requested_at,
  r.reviewed_at,
  r.approved_at,
  r.rejected_at,
  r.ordered_at,
  r.expected_delivery_date,
  r.delivery_date,
  r.completed_at,
  r.cancelled_at,
  r.rejection_reason,
  r.notes,
  r.archived_at,
  r.created_at,
  r.updated_at,
  p.project_code,
  p.name as project_name,
  c.name as client_name,
  rb.full_name as requested_by_name,
  aa.full_name as assigned_admin_name,
  coalesce(items.item_count, 0)::int as item_count,
  coalesce(items.items_summary, '') as items_summary,
  (r.required_date - public.app_today())::int as days_until_required,
  case
    when r.status in ('delivered', 'rejected', 'cancelled') then 'closed'
    when r.required_date < public.app_today() then 'overdue'
    when r.required_date = public.app_today() then 'due_today'
    when r.required_date = public.app_today() + 1 then 'due_tomorrow'
    when r.required_date <= public.app_today() + 7 then 'due_soon'
    else 'upcoming'
  end as required_state,
  -- Like-for-like: actual minus estimate over the items that carry both costs.
  case when cv.allowed then r.variance_actual_cost - r.variance_estimated_cost end as cost_variance,
  r.assigned_at
from public.material_requests r
join public.projects p on p.id = r.project_id
join public.clients c on c.id = p.client_id
cross join lateral (select public.can_view_material_cost_details(r.project_id) as allowed) as cv
left join public.profiles rb on rb.id = r.requested_by
left join public.profiles aa on aa.id = r.assigned_admin
left join lateral (
  select count(*) as item_count,
         string_agg(i.material_name || ' ' || trim_scale(i.quantity)::text || ' ' || i.unit, ', '
                    order by i.created_at, i.id) as items_summary
  from public.material_request_items i
  where i.request_id = r.id
) as items on true
where public.can_access_material_request(r.id);

-- -----------------------------------------------------------------------------
-- material_request_item_directory: request items with the same columns as
-- material_request_items. approved_unit_cost / actual_unit_cost are NULL unless
-- the caller may see approved/actual costs. API users cannot select those two
-- columns from the base table, so "select *" on items goes through this view.
-- -----------------------------------------------------------------------------
create view public.material_request_item_directory
with (security_barrier = true)
as
select
  i.id,
  i.request_id,
  i.material_id,
  i.material_name,
  i.category,
  i.quantity,
  i.unit,
  i.estimated_unit_cost,
  case when cv.allowed then i.approved_unit_cost end as approved_unit_cost,
  case when cv.allowed then i.actual_unit_cost end as actual_unit_cost,
  i.delivered_quantity,
  i.notes,
  i.created_at,
  i.updated_at
from public.material_request_items i
join public.material_requests r on r.id = i.request_id
cross join lateral (select public.can_view_material_cost_details(r.project_id) as allowed) as cv
where public.can_access_material_request(i.request_id);

-- -----------------------------------------------------------------------------
-- project_material_summary: per-project request counts and costs. Only
-- requests the caller can access are aggregated. Approved / actual totals are
-- NULL unless the caller may see approved/actual costs.
-- -----------------------------------------------------------------------------
create view public.project_material_summary
with (security_barrier = true)
as
select
  p.id as project_id,
  coalesce(s.total_requests, 0)::int as total_requests,
  coalesce(s.pending_requests, 0)::int as pending_requests,
  coalesce(s.approved_requests, 0)::int as approved_requests,
  coalesce(s.ordered_requests, 0)::int as ordered_requests,
  coalesce(s.delivered_requests, 0)::int as delivered_requests,
  coalesce(s.pending_material_cost, 0) as pending_material_cost,
  case when public.can_view_material_cost_details(p.id) then coalesce(s.approved_material_cost, 0) end
    as approved_material_cost,
  case when public.can_view_material_cost_details(p.id) then coalesce(s.actual_material_cost, 0) end
    as actual_material_cost
from public.projects p
left join lateral (
  select
    count(*) as total_requests,
    count(*) filter (where r.status in ('requested', 'pending_review')) as pending_requests,
    count(*) filter (where r.status = 'approved') as approved_requests,
    count(*) filter (where r.status in ('ordered', 'partially_delivered')) as ordered_requests,
    count(*) filter (where r.status = 'delivered') as delivered_requests,
    sum(r.estimated_cost) filter (where r.status in ('requested', 'pending_review')) as pending_material_cost,
    sum(r.approved_cost) filter (where r.status in ('approved', 'ordered', 'partially_delivered', 'delivered')) as approved_material_cost,
    sum(r.actual_cost) filter (where r.status not in ('rejected', 'cancelled')) as actual_material_cost
  from public.material_requests r
  where r.project_id = p.id
    and r.archived_at is null
    and public.can_access_material_request(r.id)
) as s on true
where public.can_access_project(p.id);

-- -----------------------------------------------------------------------------
-- team_directory: names/roles of active team members (no email or phone).
-- -----------------------------------------------------------------------------
create view public.team_directory
with (security_barrier = true)
as
select
  pr.id,
  pr.full_name,
  pr.role,
  pr.employee_id,
  pr.status,
  pr.avatar_url
from public.profiles pr
where pr.status = 'active'
  and pr.role is not null
  and public.current_app_role() is not null;

-- -----------------------------------------------------------------------------
-- activity_feed: audit rows filtered by the audit_logs RLS policy.
-- -----------------------------------------------------------------------------
create view public.activity_feed
with (security_invoker = true)
as
select
  a.id,
  a.user_id,
  a.actor_name,
  a.role,
  a.action,
  a.entity_type,
  a.entity_id,
  a.project_id,
  a.summary,
  a.metadata,
  a.metadata ->> 'project_code' as project_code,
  a.metadata ->> 'project_name' as project_name,
  a.created_at
from public.audit_logs a;

-- -----------------------------------------------------------------------------
-- Privileges: anon nothing, authenticated read-only.
-- -----------------------------------------------------------------------------
revoke all on public.project_directory, public.project_financial_summary, public.client_directory,
              public.material_request_directory, public.material_request_item_directory,
              public.project_material_summary, public.team_directory, public.activity_feed
  from public, anon, authenticated;

grant select on public.project_directory, public.project_financial_summary, public.client_directory,
                public.material_request_directory, public.material_request_item_directory,
                public.project_material_summary, public.team_directory, public.activity_feed
  to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 0007_storage_realtime_cron.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- 0007_storage_realtime_cron.sql
-- Ignite Interior Decor: private document storage, realtime publication,
-- scheduled deadline notifications and a final privilege lockdown.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Storage bucket "project-documents" (private, 25 MB per file)
-- Object path: {project_id}/{category}/{uuid}-{safe_file_name}
-- -----------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'project-documents',
  'project-documents',
  false,
  26214400,
  array[
    'image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/heif',
    'application/pdf',
    'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.ms-excel',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'text/plain', 'text/csv',
    'image/vnd.dwg', 'image/vnd.dxf', 'application/acad', 'application/dxf',
    'application/octet-stream'
  ]
)
on conflict (id) do update
  set public = false,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- Parses "{project_id}/{category}/..." safely (no cast errors on odd paths)
-- and checks the caller's access. p_write = true additionally requires the
-- owner or an assigned site manager and a valid document category folder.
create or replace function public.can_access_project_document_object(p_name text, p_write boolean)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_parts      text[];
  v_project_id uuid;
begin
  if p_name is null or public.current_app_role() is null then
    return false;
  end if;

  v_parts := storage.foldername(p_name);
  if v_parts is null or array_length(v_parts, 1) is null or array_length(v_parts, 1) < 2 then
    return false;
  end if;
  if v_parts[1] !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return false;
  end if;
  v_project_id := v_parts[1]::uuid;

  if p_write then
    if v_parts[2] not in ('photos', 'drawings', 'material_documents', 'site_reports', 'other') then
      return false;
    end if;
    if public.is_owner() then
      return exists (select 1 from public.projects p where p.id = v_project_id);
    end if;
    return public.is_project_member(v_project_id, 'site_manager')
       and exists (select 1 from public.projects p
                   where p.id = v_project_id
                     and p.archived_at is null
                     and p.status not in ('completed', 'cancelled'));
  end if;

  return public.is_owner() or public.is_project_member(v_project_id);
end
$$;

revoke all on function public.can_access_project_document_object(text, boolean) from public, anon;
grant execute on function public.can_access_project_document_object(text, boolean) to authenticated, service_role;

drop policy if exists project_documents_objects_select on storage.objects;
drop policy if exists project_documents_objects_insert on storage.objects;
drop policy if exists project_documents_objects_update on storage.objects;
drop policy if exists project_documents_objects_delete on storage.objects;

create policy project_documents_objects_select on storage.objects
  for select to authenticated
  using (bucket_id = 'project-documents' and public.can_access_project_document_object(name, false));

create policy project_documents_objects_insert on storage.objects
  for insert to authenticated
  with check (bucket_id = 'project-documents' and public.can_access_project_document_object(name, true));

-- Files are immutable for everyone except the owner (documents are archived,
-- not deleted, in project_documents).
create policy project_documents_objects_update on storage.objects
  for update to authenticated
  using (bucket_id = 'project-documents' and (select public.is_owner()))
  with check (bucket_id = 'project-documents' and (select public.is_owner()));

create policy project_documents_objects_delete on storage.objects
  for delete to authenticated
  using (bucket_id = 'project-documents' and (select public.is_owner()));

-- -----------------------------------------------------------------------------
-- Realtime: postgres_changes honour RLS and column privileges, so subscribers
-- only receive rows they may select, and never the approved/actual cost
-- columns of material_requests (not granted to API roles, see 0003).
-- material_request_comments and material_deliveries let open request pages
-- refresh when someone else comments or records a delivery.
-- -----------------------------------------------------------------------------
do $$
declare
  v_table text;
begin
  if not exists (select 1 from pg_catalog.pg_publication where pubname = 'supabase_realtime') then
    raise notice 'Publication supabase_realtime not found; realtime tables not added.';
    return;
  end if;

  foreach v_table in array array[
    'notifications', 'material_requests', 'projects', 'project_updates',
    'material_request_comments', 'material_deliveries'
  ] loop
    if not exists (
      select 1 from pg_catalog.pg_publication_tables
      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = v_table
    ) then
      execute format('alter publication supabase_realtime add table public.%I', v_table);
    end if;
  end loop;
end
$$;

-- -----------------------------------------------------------------------------
-- Daily deadline notifications at 02:30 UTC (08:00 IST) via pg_cron.
-- Skipped gracefully when pg_cron is not available (enable it under
-- Database -> Extensions and re-run this block).
-- -----------------------------------------------------------------------------
do $$
begin
  if not exists (select 1 from pg_catalog.pg_available_extensions where name = 'pg_cron') then
    raise notice 'pg_cron is not available; schedule generate_deadline_notifications() externally.';
    return;
  end if;

  create extension if not exists pg_cron with schema pg_catalog;

  execute $cron$
    select cron.schedule(
      'ignite-deadline-notifications',
      '30 2 * * *',
      'select public.generate_deadline_notifications();'
    )
  $cron$;
exception
  when others then
    raise notice 'pg_cron scheduling skipped: %', sqlerrm;
end
$$;

-- -----------------------------------------------------------------------------
-- Final lockdown: anon has no access to anything in public; functions are not
-- executable by PUBLIC unless explicitly granted above.
-- -----------------------------------------------------------------------------
revoke all on all tables in schema public from anon;
revoke all on all sequences in schema public from anon;
revoke execute on all functions in schema public from anon;
revoke execute on all functions in schema public from public;

-- Future objects created by the migration role start locked down as well.
alter default privileges in schema public revoke all on tables from anon;
alter default privileges in schema public revoke all on sequences from anon;
alter default privileges in schema public revoke execute on functions from anon, public;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 0008_profile_role_from_app_metadata.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- 0008: profile role from app_metadata set after the auth.users INSERT
--
-- Supabase Auth's admin createUser() inserts the auth.users row first and
-- writes app_metadata (role, employee_id) in a follow-up UPDATE. The
-- on_auth_user_created trigger therefore saw no role, and users created from
-- the app ended up as role-less profiles ("No access").
--
-- This migration:
--   1. copies role/employee_id from app_metadata into a still role-less
--      profile whenever app_metadata changes (only the service role can write
--      app_metadata, so the value is trusted; existing roles are never changed
--      here — role changes stay owner-controlled);
--   2. backfills profiles already affected;
--   3. stops set_user_status from activating a profile that has no role.
-- =============================================================================

create or replace function public.handle_user_app_metadata_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_role_text text := nullif(btrim(coalesce(new.raw_app_meta_data ->> 'role', '')), '');
  v_employee  text := nullif(btrim(coalesce(new.raw_app_meta_data ->> 'employee_id', '')), '');
begin
  if v_role_text is null or v_role_text not in ('owner', 'admin', 'site_manager') then
    return new;
  end if;

  -- Never let a duplicate employee ID break the auth write itself.
  if v_employee is not null and exists (
    select 1 from public.profiles p where lower(p.employee_id) = lower(v_employee) and p.id <> new.id
  ) then
    v_employee := null;
  end if;

  update public.profiles p
     set role        = v_role_text::public.app_role,
         employee_id = coalesce(p.employee_id, v_employee),
         -- A role-less profile was never working staff (deactivated staff keep
         -- their role, so they never reach this branch): its first role activates it.
         status      = 'active'::public.user_status
   where p.id = new.id
     and p.role is null;

  return new;
end
$$;

revoke all on function public.handle_user_app_metadata_change() from public, anon, authenticated;

drop trigger if exists on_auth_user_app_metadata_changed on auth.users;
create trigger on_auth_user_app_metadata_changed
  after update of raw_app_meta_data on auth.users
  for each row
  when (old.raw_app_meta_data is distinct from new.raw_app_meta_data)
  execute function public.handle_user_app_metadata_change();

-- Backfill accounts created before this fix.
update public.profiles p
   set role        = (u.raw_app_meta_data ->> 'role')::public.app_role,
       employee_id = coalesce(
                       p.employee_id,
                       case
                         when not exists (
                           select 1 from public.profiles q
                            where lower(q.employee_id) = lower(u.raw_app_meta_data ->> 'employee_id')
                              and q.id <> p.id
                         ) then nullif(btrim(u.raw_app_meta_data ->> 'employee_id'), '')
                       end
                     ),
       status      = 'active'::public.user_status
  from auth.users u
 where u.id = p.id
   and p.role is null
   and u.raw_app_meta_data ->> 'role' in ('owner', 'admin', 'site_manager');

-- A profile without a role cannot be activated (it would look active but have no access).
create or replace function public.set_user_status(p_user_id uuid, p_status public.user_status)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid         uuid := (select auth.uid());
  v_role        public.app_role := public.require_active_role();
  v_target_role public.app_role;
begin
  if v_role <> 'owner' then
    perform public.raise_app_error('NOT_AUTHORIZED', 'Only the owner can activate or deactivate users.');
  end if;
  if p_status is null then
    perform public.raise_app_error('VALIDATION', 'Status is required.');
  end if;
  if p_user_id = v_uid then
    perform public.raise_app_error('NOT_AUTHORIZED', 'You cannot change your own status.');
  end if;

  select p.role into v_target_role from public.profiles p where p.id = p_user_id for update;
  if not found then
    perform public.raise_app_error('NOT_FOUND', 'User not found.');
  end if;
  if v_target_role = 'owner' then
    perform public.raise_app_error('NOT_AUTHORIZED', 'Owner accounts cannot be deactivated.');
  end if;
  if p_status = 'active' and v_target_role is null then
    perform public.raise_app_error('VALIDATION', 'This user has no role yet. Set their role before activating them.');
  end if;

  update public.profiles p
     set status = p_status
   where p.id = p_user_id
     and p.status is distinct from p_status;
end
$$;

revoke all on function public.set_user_status(uuid, public.user_status) from public, anon;
grant execute on function public.set_user_status(uuid, public.user_status) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
-- 0009_project_payments.sql
-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

-- =============================================================================
-- 0009: client payments ledger and shareable payment statements
--
--   * project_payments: every amount the client paid, with date and mode
--     (cash, card, UPI, bank transfer, cheque, other). Owner writes; the owner
--     and members granted financial access read.
--   * project_payment_links: one secret token per project. Anyone holding the
--     link can open a read-only payment statement (/statement/<token>) without
--     signing in. The owner creates, regenerates (new token) and disables it.
--   * get_payment_statement(token): the ONLY function anon may execute. It
--     returns the statement for a valid token and NULL otherwise, and exposes
--     no internal notes, staff names or material costs.
--   * project_financial_summary.advance_received now means "amount received"
--     and is the sum of the ledger. Advances recorded before this migration are
--     copied into the ledger as opening payments (mode "other"), so totals do
--     not change. project_financials.advance_received is no longer read.
-- =============================================================================

create type public.payment_mode as enum ('cash', 'card', 'upi', 'bank_transfer', 'cheque', 'other');

-- -----------------------------------------------------------------------------
-- Tables
-- -----------------------------------------------------------------------------
create table public.project_payments (
  id          uuid primary key default gen_random_uuid(),
  project_id  uuid not null references public.projects (id) on delete cascade,
  amount      numeric(14, 2) not null check (amount > 0),
  paid_on     date not null default public.app_today(),
  mode        public.payment_mode not null,
  -- Shown to the client on the statement (UPI/transaction ID, cheque number).
  reference   text check (reference is null or length(reference) <= 120),
  -- Internal only; never returned by get_payment_statement.
  notes       text check (notes is null or length(notes) <= 1000),
  created_at  timestamptz not null default now(),
  created_by  uuid references public.profiles (id) default auth.uid(),
  updated_at  timestamptz not null default now(),
  updated_by  uuid references public.profiles (id)
);
create index project_payments_project_id_idx on public.project_payments (project_id, paid_on desc);
create index project_payments_created_by_idx on public.project_payments (created_by);
create index project_payments_updated_by_idx on public.project_payments (updated_by);

create table public.project_payment_links (
  project_id  uuid primary key references public.projects (id) on delete cascade,
  -- 256 bits of randomness; the app normally supplies its own random token.
  token       text not null unique
              default replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '')
              check (token ~ '^[A-Za-z0-9_-]{32,128}$'),
  created_at  timestamptz not null default now(),
  created_by  uuid references public.profiles (id) default auth.uid()
);
create index project_payment_links_created_by_idx on public.project_payment_links (created_by);

create trigger set_updated_at before update on public.project_payments
  for each row execute function public.set_updated_at();
create trigger set_updated_by before insert or update on public.project_payments
  for each row execute function public.set_updated_by();

-- -----------------------------------------------------------------------------
-- Backfill: advances recorded before the ledger existed become opening payments.
-- -----------------------------------------------------------------------------
insert into public.project_payments (project_id, amount, paid_on, mode, notes, created_at, created_by)
select f.project_id,
       f.advance_received,
       coalesce(p.start_date, (p.created_at at time zone 'Asia/Kolkata')::date),
       'other',
       'Advance recorded before payment tracking. Edit to set the real mode and date.',
       f.updated_at,
       f.updated_by
from public.project_financials f
join public.projects p on p.id = f.project_id
where f.advance_received > 0;

-- -----------------------------------------------------------------------------
-- Row level security
-- -----------------------------------------------------------------------------
alter table public.project_payments      enable row level security;
alter table public.project_payment_links enable row level security;

create policy project_payments_select on public.project_payments
  for select to authenticated
  using (public.can_view_project_financials(project_id));

create policy project_payments_insert on public.project_payments
  for insert to authenticated
  with check ((select public.is_owner()));

create policy project_payments_update on public.project_payments
  for update to authenticated
  using ((select public.is_owner()))
  with check ((select public.is_owner()));

create policy project_payments_delete on public.project_payments
  for delete to authenticated
  using ((select public.is_owner()));

-- Tokens are bearer secrets: only the owner can read or manage them.
create policy project_payment_links_select on public.project_payment_links
  for select to authenticated
  using ((select public.is_owner()));

create policy project_payment_links_insert on public.project_payment_links
  for insert to authenticated
  with check ((select public.is_owner()));

create policy project_payment_links_update on public.project_payment_links
  for update to authenticated
  using ((select public.is_owner()))
  with check ((select public.is_owner()));

create policy project_payment_links_delete on public.project_payment_links
  for delete to authenticated
  using ((select public.is_owner()));

revoke all on public.project_payments, public.project_payment_links from public, anon, authenticated;
grant select, insert, update, delete on public.project_payments to authenticated;
grant select, insert, update, delete on public.project_payment_links to authenticated;

-- Payment and link rows are financial: members never see them in the activity
-- feed (same rule as project_financials).
drop policy audit_logs_select on public.audit_logs;
create policy audit_logs_select on public.audit_logs
  for select to authenticated
  using (
    (select public.is_owner())
    or (
      (select public.current_app_role()) is not null
      and (
        user_id = (select auth.uid())
        or (
          project_id is not null
          and entity_type not in ('project_financials', 'project_payments', 'project_payment_links',
                                  'profiles', 'clients')
          and public.is_project_member(project_id)
        )
        or (
          (select public.is_admin())
          and entity_type in ('material_requests', 'material_request_items', 'material_deliveries',
                              'material_request_comments')
          and (metadata ->> 'request_id') is not null
          and public.can_access_material_request((metadata ->> 'request_id')::uuid)
        )
      )
      and (
        entity_type not in ('material_requests', 'material_request_items')
        or coalesce(old_data ->> 'approved_unit_cost', old_data ->> 'actual_unit_cost',
                    new_data ->> 'approved_unit_cost', new_data ->> 'actual_unit_cost',
                    old_data ->> 'approved_cost', old_data ->> 'actual_cost',
                    new_data ->> 'approved_cost', new_data ->> 'actual_cost',
                    old_data ->> 'variance_estimated_cost', new_data ->> 'variance_estimated_cost',
                    old_data ->> 'variance_actual_cost', new_data ->> 'variance_actual_cost') is null
        or public.can_view_material_cost_details(project_id)
      )
    )
  );

-- -----------------------------------------------------------------------------
-- Audit trail (readable summaries; tokens are never written to the log)
-- -----------------------------------------------------------------------------
create or replace function public.audit_project_payment()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor        uuid := auth.uid();
  v_actor_name   text;
  v_actor_role   public.app_role;
  v_label        text;
  v_row          jsonb;
  v_project_id   uuid;
  v_project_code text;
  v_project_name text;
  v_action       text := lower(tg_op);
  v_summary      text;
  v_old          jsonb;
  v_new          jsonb;
  v_mode         text;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    v_old := to_jsonb(old);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    v_new := to_jsonb(new);
  end if;
  v_row := coalesce(v_new, v_old);
  v_project_id := (v_row ->> 'project_id')::uuid;

  select p.full_name, p.role into v_actor_name, v_actor_role
  from public.profiles p where p.id = v_actor;
  if v_actor is not null and v_actor_name is null then
    v_actor := null;
  end if;
  v_label := coalesce(coalesce(public.humanize(v_actor_role::text) || ' ', '') || v_actor_name, 'System');

  -- The project row is already gone when a cascade removes its payments.
  select p.project_code, p.name into v_project_code, v_project_name
  from public.projects p where p.id = v_project_id;
  if v_project_code is null and tg_op = 'DELETE' then
    return null;
  end if;

  if tg_table_name = 'project_payments' then
    v_old := v_old - 'updated_at' - 'updated_by';
    v_new := v_new - 'updated_at' - 'updated_by';
    if tg_op = 'UPDATE' and v_old = v_new then
      return null;
    end if;
    if tg_op = 'INSERT' then
      v_mode := public.humanize(new.mode::text);
      v_summary := format('%s recorded a payment of %s (%s) for %s', v_label, public.format_inr(new.amount),
                          case when new.mode = 'upi' then 'UPI' else v_mode end, v_project_code);
    elsif tg_op = 'DELETE' then
      v_summary := format('%s deleted a payment of %s dated %s for %s', v_label, public.format_inr(old.amount),
                          to_char(old.paid_on, 'DD Mon YYYY'), v_project_code);
    else
      v_summary := format('%s edited a payment of %s for %s', v_label, public.format_inr(new.amount), v_project_code);
    end if;
  else
    v_old := v_old - 'token';
    v_new := v_new - 'token';
    v_summary := case tg_op
      when 'INSERT' then format('%s created the client payment link of %s', v_label, v_project_code)
      when 'UPDATE' then format('%s regenerated the client payment link of %s', v_label, v_project_code)
      else format('%s disabled the client payment link of %s', v_label, v_project_code)
    end;
  end if;

  insert into public.audit_logs (
    user_id, actor_name, role, action, entity_type, entity_id, project_id,
    summary, old_data, new_data, metadata
  ) values (
    v_actor, coalesce(v_actor_name, 'System'), v_actor_role, v_action, tg_table_name,
    case when tg_table_name = 'project_payments' then (v_row ->> 'id')::uuid else v_project_id end,
    v_project_id, v_summary, v_old, v_new,
    jsonb_build_object('project_code', v_project_code, 'project_name', v_project_name)
  );
  return null;
end
$$;

create trigger audit_row_change after insert or update or delete on public.project_payments
  for each row execute function public.audit_project_payment();
create trigger audit_row_change after insert or update or delete on public.project_payment_links
  for each row execute function public.audit_project_payment();

-- -----------------------------------------------------------------------------
-- project_financial_summary: advance_received is now the ledger total.
-- Columns are appended so existing callers keep working.
-- -----------------------------------------------------------------------------
create or replace view public.project_financial_summary
with (security_barrier = true)
as
select
  p.id as project_id,
  p.project_code,
  p.name as project_name,
  p.client_id,
  c.name as client_name,
  p.status,
  p.archived_at,
  coalesce(f.project_cost, 0) as project_cost,
  coalesce(pay.received, 0)::numeric as advance_received,
  coalesce(mc.estimated, 0) as material_estimated_cost,
  coalesce(mc.approved, 0) as material_approved_cost,
  coalesce(mc.actual, 0) as material_actual_cost,
  (coalesce(mc.variance_actual, 0) - coalesce(mc.variance_estimated, 0)) as material_variance,
  coalesce(mc.variance_estimated, 0) as material_variance_estimated_cost,
  coalesce(mc.variance_actual, 0) as material_variance_actual_cost,
  coalesce(pay.payment_count, 0)::int as payment_count,
  pay.last_paid_on as last_payment_on
from public.projects p
join public.clients c on c.id = p.client_id
left join public.project_financials f on f.project_id = p.id
left join lateral (
  select sum(pp.amount) as received, count(*) as payment_count, max(pp.paid_on) as last_paid_on
  from public.project_payments pp
  where pp.project_id = p.id
) as pay on true
left join lateral (
  select sum(r.estimated_cost) as estimated,
         sum(r.approved_cost) as approved,
         sum(r.actual_cost) as actual,
         sum(r.variance_estimated_cost) as variance_estimated,
         sum(r.variance_actual_cost) as variance_actual
  from public.material_requests r
  where r.project_id = p.id
    and r.archived_at is null
    and r.status not in ('rejected', 'cancelled')
) as mc on true
where public.can_view_project_financials(p.id);

revoke all on public.project_financial_summary from public, anon, authenticated;
grant select on public.project_financial_summary to authenticated;

-- -----------------------------------------------------------------------------
-- Public statement for a share token (anon + authenticated).
-- -----------------------------------------------------------------------------
create or replace function public.get_payment_statement(p_token text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_project_id uuid;
  v_cost       numeric;
  v_received   numeric;
  v_result     jsonb;
begin
  if p_token is null or p_token !~ '^[A-Za-z0-9_-]{32,128}$' then
    return null;
  end if;

  select l.project_id into v_project_id
  from public.project_payment_links l
  where l.token = p_token;
  if v_project_id is null then
    return null;
  end if;

  select coalesce(f.project_cost, 0) into v_cost
  from public.project_financials f where f.project_id = v_project_id;
  select coalesce(sum(pp.amount), 0) into v_received
  from public.project_payments pp where pp.project_id = v_project_id;
  v_cost := coalesce(v_cost, 0);

  select jsonb_build_object(
    'company', (
      select jsonb_build_object('name', s.company_name, 'phone', s.phone, 'email', s.email,
                                'address', s.address, 'logo_url', s.logo_url)
      from public.company_settings s where s.id = 1
    ),
    'project', jsonb_build_object(
      'code', p.project_code,
      'name', p.name,
      'city', p.city,
      'status', p.status,
      'client_name', c.name
    ),
    'totals', jsonb_build_object(
      'project_cost', v_cost,
      'received', v_received,
      'balance', v_cost - v_received
    ),
    'by_mode', coalesce((
      select jsonb_agg(jsonb_build_object('mode', m.mode, 'amount', m.amount, 'count', m.n) order by m.amount desc)
      from (
        select pp.mode, sum(pp.amount) as amount, count(*) as n
        from public.project_payments pp
        where pp.project_id = v_project_id
        group by pp.mode
      ) m
    ), '[]'::jsonb),
    'payments', coalesce((
      select jsonb_agg(jsonb_build_object('paid_on', pp.paid_on, 'mode', pp.mode, 'amount', pp.amount,
                                          'reference', pp.reference)
                       order by pp.paid_on desc, pp.created_at desc)
      from public.project_payments pp
      where pp.project_id = v_project_id
    ), '[]'::jsonb),
    'generated_at', pg_catalog.now()
  )
  into v_result
  from public.projects p
  join public.clients c on c.id = p.client_id
  where p.id = v_project_id;

  return v_result;
end
$$;

revoke all on function public.audit_project_payment() from public, anon, authenticated;
revoke all on function public.get_payment_statement(text) from public;
grant execute on function public.get_payment_statement(text) to anon, authenticated, service_role;

commit;
